# Map sign language code to dictionary
_DICTIONARIES: dict[str, dict[str, dict]] = {
    "asl": ASL_SIGN_DICTIONARY,
    "isl": ISL_SIGN_DICTIONARY,
    "bsl": BSL_SIGN_DICTIONARY,
}

# Words to strip from gloss (articles, prepositions, copulas, etc.)
_STOP_WORDS: set[str] = {
    "THE", "A", "AN", "IS", "ARE", "AM", "WAS", "WERE", "BE", "BEEN",
    "BEING", "TO", "OF", "IN", "ON", "AT", "FOR", "IT", "ITS",
    "THAT", "THIS", "THESE", "THOSE", "DO", "DOES", "DID", "HAVE", "HAS",
    "HAD", "WILL", "SHALL", "WOULD", "SHOULD", "COULD", "CAN", "MAY",
    "MIGHT", "MUST",
}


# ── Public API ───────────────────────────────────────────────────────────────

def text_to_gloss(
    text: str,
    sign_language: str = "asl",
) -> list[dict]:
    """
    Convert English *text* into a list of gloss tokens with animation data.

    Returns a list of dicts::

        [
            {
                "gloss": "HELLO",
                "type": "sign",           # or "fingerspell"
                "duration_ms": 600,
                "animation_data": { ... },
            },
            ...
        ]
    """
    dictionary = _DICTIONARIES.get(sign_language.lower(), ASL_SIGN_DICTIONARY)
    tokens = _text_to_tokens(text)
    result: list[dict] = []

    for token in tokens:
        upper = token.upper()

        # Skip stop-words
        if upper in _STOP_WORDS:
            continue

        sign_data = dictionary.get(upper)
        if sign_data:
            result.append({
                "gloss": upper,
                "type": "sign",
                "duration_ms": sign_data["duration_ms"],
                "animation_data": {
                    "hand_shape": sign_data["hand_shape"],
                    "location": sign_data["location"],
                    "movement": sign_data["movement"],
                    "two_handed": sign_data["two_handed"],
                    "bone_rotations": sign_data["bone_rotations"],
                    "facial_expression": sign_data["facial_expression"],
                    "head_tilt": sign_data["head_tilt"],
                    "body_lean": sign_data["body_lean"],
                },
            })
        else:
            # Fingerspell unknown words letter-by-letter
            for char in upper:
                if char.isalpha():
                    result.append({
                        "gloss": char,
                        "type": "fingerspell",
                        "duration_ms": 250,
                        "animation_data": _fingerspell_data(char),
                    })

    return result


def text_to_sign_sequence(
    segments: list[dict],
    sign_language: str = "asl",
) -> list[dict]:
    """
    Convert translated text segments into a timed sign sequence
    aligned with video timestamps.
    """
    gloss_sequence = []

    for seg in segments:
        text = seg.get("translated_text", seg.get("text", ""))
        seg_start = seg.get("start", 0)
        seg_end = seg.get("end", 0)
        seg_duration = max(seg_end - seg_start, 0.5)

        tokens = text_to_gloss(text, sign_language)
        if not tokens:
            continue

        # Calculate total token duration
        total_ms = sum(t["duration_ms"] for t in tokens)
        if total_ms <= 0:
            continue

        # Scale tokens to fit within segment duration
        scale = (seg_duration * 1000) / total_ms
        time_offset = seg_start

        for token in tokens:
            scaled_duration = token["duration_ms"] * scale / 1000
            token["start_time"] = round(time_offset, 3)
            token["end_time"] = round(time_offset + scaled_duration, 3)
            time_offset = token["end_time"]
            gloss_sequence.append(token)

    return gloss_sequence


def get_available_signs(sign_language: str = "asl") -> list[str]:
    """Return sorted list of all signs in the dictionary."""
    dictionary = _DICTIONARIES.get(sign_language.lower(), ASL_SIGN_DICTIONARY)
    return sorted(dictionary.keys())


def get_supported_languages() -> list[dict]:
    """Return list of supported sign languages with metadata."""
    return [
        {
            "code": "asl",
            "name": "American Sign Language",
            "description": "Used in the United States and English-speaking Canada",
            "word_count": len(ASL_SIGN_DICTIONARY),
        },
        {
            "code": "isl",
            "name": "Indian Sign Language",
            "description": "Used across India and South Asia",
            "word_count": len(ISL_SIGN_DICTIONARY),
        },
        {
            "code": "bsl",
            "name": "British Sign Language",
            "description": "Used in the United Kingdom",
            "word_count": len(BSL_SIGN_DICTIONARY),
        },
    ]


# ── Internal helpers ─────────────────────────────────────────────────────────

def _text_to_tokens(text: str) -> list[str]:
    """Tokenize text into words, stripping punctuation."""
    cleaned = re.sub(r"[^\w\s]", "", text)
    return cleaned.split()


def _fingerspell_data(letter: str) -> dict:
    """Return animation data for a single fingerspelled letter."""
    # Each letter gets a distinct hand position based on ASL alphabet
    letter = letter.upper()
    # Slight variation in hand rotation per letter for visual distinction
    offset = (ord(letter) - ord("A")) * 0.12
    return {
        "hand_shape": f"fs_{letter}",
        "location": "center",
        "movement": "hold",
        "two_handed": False,
        "letter": letter,
        "bone_rotations": {
            "left_upper_arm": (0, 0, 0.3),
            "left_lower_arm": (-0.4, 0, 0),
            "left_hand": (0, 0, 0),
            "right_upper_arm": (-1.2, 0.1, -0.3),
            "right_lower_arm": (-0.8, 0, 0),
            "right_hand": (round(offset * 0.3, 3), round(offset * 0.2, 3), round(offset * 0.1, 3)),
        },
        "facial_expression": "neutral",
        "head_tilt": "none",
        "body_lean": "none",
    }
